/* FRAME/12 Design System — Tokens, Panel Grammar, Screentone, and Motion on Twos.
   Works standalone without Tailwind. */

:root {
  --f-desk: #e2e3e5;
  --f-sheet: #ffffff;
  --f-panel: #ffffff;
  --f-ink: #121212;
  --f-ink-2: #4b4b4b;
  --f-rule: #121212;
  --f-tone: #121212;
  --f-grid: #e3e3e3;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #e2e3e5;

  --f-gutter-pair: 12px;
  --f-gutter-scene: 20px;
  --f-gutter-change: 32px;

  --font-f-display: "Dela Gothic One", "Arial Black", "Helvetica Neue", sans-serif;
  --font-f-body: "Zen Kaku Gothic New", "Hiragino Sans", "Helvetica Neue", Arial, sans-serif;
  --font-f-mono: "M PLUS 1 Code", ui-monospace, "SF Mono", Menlo, monospace;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --f-desk: #000000;
    --f-sheet: #050505;
    --f-panel: #19191a;
    --f-ink: #f1f0ea;
    --f-ink-2: #b9b8b1;
    --f-rule: #f1f0ea;
    --f-tone: #f1f0ea;
    --f-grid: #2c2c2d;
    --f-marker: #ffd60a;
    --f-marker-ink: #121212;
    --f-hole: #000000;
    color-scheme: dark;
  }
}

:root[data-theme="dark"] {
  --f-desk: #000000;
  --f-sheet: #050505;
  --f-panel: #19191a;
  --f-ink: #f1f0ea;
  --f-ink-2: #b9b8b1;
  --f-rule: #f1f0ea;
  --f-tone: #f1f0ea;
  --f-grid: #2c2c2d;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #000000;
  color-scheme: dark;
}

.theme-light {
  --f-desk: #e2e3e5;
  --f-sheet: #ffffff;
  --f-panel: #ffffff;
  --f-ink: #121212;
  --f-ink-2: #4b4b4b;
  --f-rule: #121212;
  --f-tone: #121212;
  --f-grid: #e3e3e3;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #e2e3e5;
  color-scheme: light;
}

.theme-dark {
  --f-desk: #000000;
  --f-sheet: #050505;
  --f-panel: #19191a;
  --f-ink: #f1f0ea;
  --f-ink-2: #b9b8b1;
  --f-rule: #f1f0ea;
  --f-tone: #f1f0ea;
  --f-grid: #2c2c2d;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #000000;
  color-scheme: dark;
}

/* ===================================================================== Base & Reset */
.dash,
.sheet,
.scene,
.panel,
.pair,
.rng,
.metric,
.chart,
.ints,
.f12-btn,
.f12-field,
.f12-input,
.f12-dialog,
.f12-select,
.f12-tooltip-wrap,
.f12-menu-wrap,
.f12-table-wrap {
  box-sizing: border-box;
}
.dash *,
.dash *::before,
.dash *::after,
.sheet *,
.sheet *::before,
.sheet *::after,
.panel *,
.panel *::before,
.panel *::after,
.f12-dialog *,
.f12-select *,
.f12-table-wrap * {
  box-sizing: border-box;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

button {
  font: inherit;
  color: inherit;
}

:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}

/* ===================================================================== Sheet & Pegs */
.dash {
  container-type: inline-size;
  position: relative;
}
.dash h2,
.dash h3,
.dash p,
.dash ul {
  margin: 0;
}
.dash ul {
  list-style: none;
  padding: 0;
}

.frame {
  background: var(--f-desk);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  padding: 20px;
  border-radius: 4px;
}

.sheet,
.frame .sheet {
  position: relative;
  background: var(--f-sheet);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  padding: 44px 28px 28px;
  display: flex;
  flex-direction: column;
  gap: 32px; /* 32 = scene change */
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.05), 0 18px 40px -26px rgba(0, 0, 0, 0.5);
}

.pegs,
.frame .pegs {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 26px;
  align-items: center;
}
.peg,
.frame .peg {
  display: block;
  background: var(--f-hole);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.25);
}
.peg.round,
.frame .peg.round {
  width: 11px;
  height: 11px;
  border-radius: 50%;
}
.peg.slot,
.frame .peg.slot {
  width: 26px;
  height: 8px;
  border-radius: 4px;
}

.hd,
.frame .hd {
  display: flex;
  flex-wrap: wrap;
  gap: 16px 24px;
  align-items: flex-end;
  justify-content: space-between;
}
.eyebrow,
.frame .eyebrow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.title,
.frame .title {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: clamp(30px, 5.2cqi, 46px);
  line-height: 1.02;
  margin-top: 10px;
  letter-spacing: 0.005em;
  text-wrap: balance;
}
.sub,
.frame .sub {
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink-2);
  margin-top: 8px;
  letter-spacing: 0.04em;
}

/* ===================================================================== Scene & Gutter Grammar
   12px = pair, 20px = same scene, 32px = scene change */
.scene,
.frame .scene {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
  gap: 20px;
  min-width: 0;
}
.scene.scene-split,
.frame .scene.scene-split {
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
}
.scene.scene-stack,
.frame .scene.scene-stack {
  grid-template-columns: minmax(0, 1fr);
}
.scene.scene-equal,
.frame .scene.scene-equal {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.scene.scene-three,
.frame .scene.scene-three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.scene.scene-pair,
.frame .scene.scene-pair {
  gap: 12px;
}
.scene.scene-scene,
.frame .scene.scene-scene {
  gap: 20px;
}
.scene.scene-change,
.frame .scene.scene-change {
  gap: 32px;
}

.pair,
.frame .pair {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}
.pair > .panel,
.frame .pair .panel {
  flex: 1;
}

/* ===================================================================== Panel */
.panel,
.frame .panel {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  color: var(--f-ink);
  font-family: var(--font-f-body);
}
.panel-frame,
.frame .panel-frame {
  position: absolute;
  inset: 0;
  overflow: visible;
  pointer-events: none;
}
.panel-frame polygon,
.frame .panel-frame polygon {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2.5;
  stroke-linejoin: miter;
}
.panel-body,
.frame .panel-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  position: relative;
  padding: 24px 22px 22px;
}
.panel.slant-bottom .panel-body,
.frame .panel.slant-bottom .panel-body {
  padding-bottom: 36px;
}
.panel.slant-top .panel-body,
.frame .panel.slant-top .panel-body {
  padding-top: 36px;
}
.cut,
.frame .cut {
  position: absolute;
  top: -8px;
  left: 16px;
  z-index: 1;
  padding: 0 6px;
  line-height: 16px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.12em;
  background: var(--f-sheet);
  color: var(--f-ink);
}
.panel.slant-top .cut,
.frame .panel.slant-top .cut {
  top: 8px;
}

/* ===================================================================== Tag & Badge */
.tag,
.frame .tag {
  display: inline-block;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-marker-ink);
  background: var(--f-marker);
  padding: 1px 6px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.badge,
.frame .badge {
  position: relative;
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 2px 7px;
  background: var(--f-marker);
  color: var(--f-marker-ink);
  border: 2px solid var(--f-rule);
}
.badge-t {
  position: relative;
  z-index: 1;
}
.burst {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 150%;
  height: auto;
  transform: translate(-50%, -50%);
  opacity: 0;
  pointer-events: none;
}
.burst line,
.frame .burst line {
  stroke: var(--f-ink);
  stroke-width: 2;
  stroke-linecap: square;
}

/* ===================================================================== SegmentedControl (RangeTabs) */
.rng,
.frame .rng {
  position: relative;
  display: inline-flex;
  flex: none;
  isolation: isolate;
  border: 2.5px solid var(--f-rule);
  background: var(--f-panel);
}
.rng-ind,
.frame .rng-ind {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  background: #ffffff;
  mix-blend-mode: difference;
  pointer-events: none;
}
.rng-btn,
.frame .rng-btn {
  cursor: pointer;
  background: none;
  border: 0;
  display: grid;
  justify-items: center;
  padding: 6px 16px 5px;
  color: var(--f-ink);
  min-width: 64px;
}
.rng-btn + .rng-btn,
.frame .rng-btn + .rng-btn {
  border-left: 2px solid var(--f-rule);
}
.rng-n,
.frame .rng-n {
  font-family: var(--font-f-display);
  font-size: 18px;
  line-height: 1;
}
.rng-u,
.frame .rng-u {
  font-family: var(--font-f-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.rng-btn:focus-visible,
.frame .rng-btn:focus-visible {
  outline: 3px solid var(--f-marker);
  outline-offset: -6px;
}

/* ===================================================================== Button & Input */
.f12-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  font-family: var(--font-f-mono);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 2.5px solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
  padding: 8px 16px;
  font-size: 12px;
  line-height: 1.2;
}
.f12-btn-sm {
  padding: 5px 10px;
  font-size: 11px;
}
.f12-btn-md {
  padding: 8px 16px;
  font-size: 12px;
}
.f12-btn-lg {
  padding: 12px 22px;
  font-size: 13px;
}
.f12-btn-primary {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-btn-secondary {
  background: var(--f-panel);
  color: var(--f-ink);
}
.f12-btn-marker {
  background: var(--f-marker);
  color: var(--f-marker-ink);
}
.f12-btn:hover:not(:disabled) {
  box-shadow: 3px 3px 0 var(--f-rule);
}
.f12-btn:active:not(:disabled) {
  box-shadow: none;
}
.f12-btn:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-btn:disabled {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  background: var(--f-panel);
}

.f12-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-input {
  width: 100%;
  padding: 9px 12px;
  font-family: var(--font-f-body);
  font-size: 14px;
  line-height: 1.4;
  color: var(--f-ink);
  background: var(--f-panel);
  border: 2.5px solid var(--f-rule);
  border-radius: 0;
}
.f12-input::placeholder {
  color: var(--f-ink-2);
}
.f12-input:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-hint {
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-error {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink);
  margin: 0;
}
.f12-error-flag {
  background: var(--f-marker);
  color: var(--f-marker-ink);
  padding: 0 4px;
  font-weight: 700;
}

/* ===================================================================== Metric, Delta & Spark */
.metric {
  display: flex;
  flex-direction: column;
  flex: 1;
}
.m-label,
.frame .m-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  margin: 0;
}
.m-value,
.frame .m-value {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: 34px;
  line-height: 1.05;
  margin: 10px 0 0;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
  color: var(--f-ink);
}
.metric.big .m-value,
.frame .metric.big .m-value {
  font-size: clamp(36px, 6cqi, 56px);
}
.delta,
.frame .delta {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
  font-variant-numeric: tabular-nums;
  font-family: var(--font-f-mono);
  font-size: 12px;
  margin: 10px 0 0;
  letter-spacing: 0.02em;
  color: var(--f-ink);
}
.delta-sym,
.frame .delta-sym {
  font-size: 10px;
}
.delta.up .delta-sym,
.delta.down .delta-sym,
.frame .delta.up .delta-sym,
.frame .delta.down .delta-sym {
  color: var(--f-marker-ink);
  background: var(--f-marker);
  padding: 0 3px;
}
.delta-ref,
.frame .delta-ref {
  color: var(--f-ink-2);
}
.m-note,
.frame .m-note {
  font-size: 13px;
  color: var(--f-ink-2);
  margin: 6px 0 0;
  max-width: 30ch;
}

.spark {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: auto;
  padding-top: 16px;
}
.spark svg,
.frame .spark svg {
  display: block;
  border-bottom: 2px solid var(--f-rule);
  overflow: visible;
}
.spark-l,
.frame .spark-l {
  font-family: var(--font-f-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  margin: 0;
}
.spark-bar,
.frame .spark-bar {
  stroke: var(--f-ink);
  stroke-width: 1;
}

/* ===================================================================== Chart, Balloon & Data Table */
.c01-hd,
.frame .c01-hd {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: flex-end;
  gap: 12px 24px;
  margin-bottom: 4px;
}
.legend,
.legend-hint,
.frame .legend,
.frame .legend-hint {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--f-ink-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}
.legend-hint,
.frame .legend-hint {
  max-width: 26ch;
}
.sw {
  display: inline-block;
  width: 14px;
  height: 0;
  border-top-width: 2px;
  border-top-style: solid;
  flex: none;
}
.sw-total,
.frame .sw-total {
  border-color: var(--f-ink);
  border-top-width: 2.5px;
}
.sw-focus,
.frame .sw-focus {
  border-color: var(--f-ink);
  border-top-style: dashed;
}

.chart {
  position: relative;
  width: 100%;
  touch-action: pan-y;
}
.chart-svg {
  display: block;
  overflow: visible;
}
.chart-svg:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 4px;
}
.chart text,
.frame .chart text {
  fill: var(--f-ink-2);
  font-family: var(--font-f-mono);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}
.grid,
.frame .grid {
  stroke: var(--f-grid);
}
.baseline,
.frame .baseline {
  stroke: var(--f-rule);
  stroke-width: 2;
}
.sheet-ticks line,
.frame .sheet-ticks line {
  stroke: var(--f-rule);
  stroke-width: 1;
}
.tone-dot,
.frame .tone-dot {
  fill: var(--f-tone);
}
.l-total,
.frame .l-total {
  stroke: var(--f-ink);
  stroke-width: 2.5;
  stroke-linejoin: round;
  stroke-linecap: round;
}
.l-focus,
.frame .l-focus {
  stroke: var(--f-ink);
  stroke-width: 2;
  stroke-dasharray: 6 4;
  stroke-linejoin: round;
}
.tail,
.frame .tail {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2;
  stroke-linejoin: miter;
}
.peak-dot,
.frame .peak-dot {
  fill: var(--f-marker);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.balloon,
.frame .balloon {
  position: absolute;
  z-index: 2;
  white-space: nowrap;
  display: flex;
  align-items: center;
  padding: 0 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  border-radius: 14px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
}
.balloon-gap,
.frame .balloon-gap {
  position: absolute;
  bottom: -2px;
  width: 10px;
  height: 3px;
  background: var(--f-panel);
}
.balloon-standalone {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
}
.balloon-standalone .balloon {
  position: relative;
  height: 28px;
}
.balloon-standalone-svg {
  display: block;
  overflow: visible;
  margin-top: -1px;
}

.cross line,
.frame .cross line {
  stroke: var(--f-ink);
  stroke-width: 1;
}
.cross-dot,
.frame .cross-dot {
  fill: var(--f-marker);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.cross-dot2,
.frame .cross-dot2 {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.tip,
.frame .tip {
  position: absolute;
  z-index: 3;
  pointer-events: none;
  display: grid;
  gap: 2px;
  min-width: 160px;
  padding: 8px 10px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  background: var(--f-panel);
  border: 2px solid var(--f-rule);
  color: var(--f-ink);
  font-family: var(--font-f-mono);
  box-shadow: 4px 4px 0 var(--f-rule);
}
.tip span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tbl,
.frame .tbl {
  margin-top: 10px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink);
}
.tbl summary,
.frame .tbl summary {
  cursor: pointer;
  width: max-content;
  padding: 4px 0;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.tbl-scroll {
  max-height: 240px;
  overflow: auto;
  margin-top: 6px;
}
.tbl table {
  border-collapse: collapse;
  width: 100%;
  font-variant-numeric: tabular-nums;
}
.tbl th,
.tbl td {
  text-align: left;
  padding: 5px 10px 5px 0;
  white-space: nowrap;
}
.tbl th,
.frame .tbl th {
  color: var(--f-ink-2);
  font-weight: 500;
  border-bottom: 2px solid var(--f-rule);
}
.tbl td,
.frame .tbl td {
  border-bottom: 1px solid var(--f-grid);
}

/* ===================================================================== ToneBarList (Interventions) */
.ints-hd,
.frame .ints-hd {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 6px 16px;
  margin-bottom: 14px;
}
.ints-sub,
.frame .ints-sub {
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
  letter-spacing: 0.04em;
  margin: 0;
}
.ints-list,
.frame .ints-list {
  display: grid;
  list-style: none;
  padding: 0;
  margin: 0;
}
.ints-list li + li,
.frame .ints-list li + li {
  border-top: 1px solid var(--f-grid);
}
.int-row,
.frame .int-row {
  all: unset;
  box-sizing: border-box;
  cursor: pointer;
  display: grid;
  width: 100%;
  align-items: center;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 2fr) auto;
  gap: 16px;
  padding: 12px 8px;
  color: var(--f-ink);
}
.int-row:hover .int-name,
.frame .int-row:hover .int-name {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.int-row:focus-visible,
.frame .int-row:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -3px;
}
.int-name,
.frame .int-name {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex-wrap: wrap;
  font-size: 15px;
  font-weight: 700;
}
.int-bar,
.frame .int-bar {
  position: relative;
  display: block;
  height: 16px;
  border: 2px solid var(--f-rule);
}
.int-fill,
.frame .int-fill {
  position: absolute;
  inset: 0 auto 0 0;
  background-image: radial-gradient(circle, var(--f-tone) 1.1px, transparent 1.4px);
  background-size: 5px 5px;
  border-right: 2px solid var(--f-rule);
}
.int-row[aria-pressed="true"],
.frame .int-row[aria-pressed="true"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.int-row[aria-pressed="true"] .int-bar,
.frame .int-row[aria-pressed="true"] .int-bar {
  border-color: var(--f-panel);
}
.int-row[aria-pressed="true"] .int-fill,
.frame .int-row[aria-pressed="true"] .int-fill {
  background: var(--f-marker);
  border-right-color: var(--f-panel);
}
.int-row[aria-pressed="true"] .int-share,
.frame .int-row[aria-pressed="true"] .int-share {
  color: var(--f-panel);
}
.int-row[aria-pressed="true"] .badge,
.frame .int-row[aria-pressed="true"] .badge {
  border-color: var(--f-panel);
}
.int-val,
.frame .int-val {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  font-family: var(--font-f-mono);
  font-size: 13px;
  font-weight: 500;
}
.int-share,
.frame .int-share {
  min-width: 3ch;
  text-align: right;
  color: var(--f-ink-2);
}

/* ===================================================================== Adapters: Dialog, Select, Tooltip, DropdownMenu, Table */

/* Dialog */
dialog.f12-dialog {
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2.5px solid var(--f-rule);
  box-shadow: 6px 6px 0 var(--f-rule);
  padding: 24px 22px 22px;
  max-width: 480px;
  width: calc(100% - 32px);
  font-family: var(--font-f-body);
}
dialog.f12-dialog:modal {
  overscroll-behavior: contain;
}
dialog.f12-dialog::backdrop {
  overflow: hidden;
  overscroll-behavior: contain;
  background-color: rgba(18, 18, 18, 0.55);
  background-image: radial-gradient(circle, var(--f-ink) 1px, transparent 1.5px);
  background-size: 6px 6px;
}
.f12-dialog-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}
.f12-dialog-title {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: 24px;
  line-height: 1.1;
  color: var(--f-ink);
  margin: 0;
}
.f12-dialog-description {
  font-size: 14px;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 20px;
}

/* Select */
.f12-select {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  gap: 6px;
  min-width: 180px;
  font-family: var(--font-f-body);
}
.f12-select-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  padding: 8px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2.5px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
}
.f12-select-trigger:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-select-caret {
  display: inline-block;
  padding: 1px 4px;
  font-size: 10px;
  background: var(--f-marker);
  color: var(--f-marker-ink);
  border: 1.5px solid var(--f-rule);
  line-height: 1;
}
.f12-select-content {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 20;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2.5px solid var(--f-rule);
  box-shadow: 4px 4px 0 var(--f-rule);
  list-style: none;
  margin: 0;
  padding: 0;
}
.f12-select-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 8px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 0;
  border-bottom: 1px solid var(--f-grid);
  font-family: var(--font-f-mono);
  font-size: 12px;
  cursor: pointer;
  text-align: left;
}
.f12-select-item:last-child {
  border-bottom: 0;
}
.f12-select-item:hover,
.f12-select-item[aria-selected="true"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-select-item:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -3px;
}
.f12-select-check {
  background: var(--f-marker);
  color: var(--f-marker-ink);
  padding: 0 4px;
  font-size: 10px;
  font-weight: 700;
}

/* Tooltip */
.f12-tooltip-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}
.f12-tooltip {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 25;
  white-space: nowrap;
  padding: 5px 10px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  box-shadow: 3px 3px 0 var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 11px;
  pointer-events: none;
}

/* DropdownMenu */
.f12-menu-wrap {
  position: relative;
  display: inline-block;
}
.f12-menu {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  z-index: 20;
  min-width: 180px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2.5px solid var(--f-rule);
  box-shadow: 4px 4px 0 var(--f-rule);
  padding: 4px 0;
}
.f12-menu-label {
  padding: 6px 12px 4px;
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-menu-sep {
  height: 1px;
  background: var(--f-grid);
  margin: 4px 0;
}
.f12-menu-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 7px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 0;
  font-family: var(--font-f-body);
  font-size: 13px;
  cursor: pointer;
  text-align: left;
}
.f12-menu-item:hover,
.f12-menu-item:focus-visible {
  background: var(--f-ink);
  color: var(--f-panel);
  outline: none;
}

/* Table */
.f12-table-wrap {
  width: 100%;
  overflow-x: auto;
}
.f12-table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-f-body);
  font-size: 13px;
  color: var(--f-ink);
  font-variant-numeric: tabular-nums;
}
.f12-table caption {
  caption-side: bottom;
  padding-top: 8px;
  text-align: left;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
}
.f12-table th,
.f12-table td {
  text-align: left;
  padding: 8px 12px 8px 0;
  border-bottom: 1px solid var(--f-grid);
}
.f12-table thead th {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  border-bottom: 2.5px solid var(--f-rule);
}
.f12-table tfoot td,
.f12-table tfoot th {
  font-family: var(--font-f-mono);
  font-weight: 700;
  border-top: 2px solid var(--f-rule);
  border-bottom: 0;
}

/* ===================================================================== Responsive Container Rules */
@container (max-width: 760px) {
  .frame {
    padding: 6px;
  }
  .sheet,
  .frame .sheet {
    padding: 40px 14px 18px;
    gap: 24px;
  }
  .scene,
  .frame .scene,
  .scene.scene-split,
  .scene.scene-equal,
  .scene.scene-three {
    grid-template-columns: minmax(0, 1fr);
  }
  .panel-body,
  .frame .panel-body {
    padding: 22px 14px 18px;
  }
  .int-row,
  .frame .int-row {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "name val" "bar bar";
    gap: 8px 12px;
  }
  .int-name,
  .frame .int-name {
    grid-area: name;
  }
  .int-val,
  .frame .int-val {
    grid-area: val;
  }
  .int-bar,
  .frame .int-bar {
    grid-area: bar;
  }
  .m-value,
  .frame .m-value {
    font-size: 30px;
  }
}

/* ===================================================================== Motion Grammar
   smooth  = continuous easing
   stepped = poses held on twos: 12 drawings/s, each pose 83.33ms
   cut     = instant, editorial hard cut */
.m-smooth .rng-ind {
  transition: transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1), width 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.m-stepped .rng-ind {
  transition: transform 250ms steps(3, end), width 250ms steps(3, end);
}
.m-smooth .rng-btn {
  transition: color 180ms ease 60ms;
}
.m-stepped .rng-btn {
  transition: color 0ms linear 166ms;
}

.m-smooth .enter {
  animation: enterSmooth 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes enterSmooth {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.m-stepped .enter {
  animation: enterStep 250ms;
  animation-timing-function: step-end;
}
@keyframes enterStep {
  0% {
    opacity: 0.35;
    transform: translateY(10px);
  }
  33% {
    opacity: 0.8;
    transform: translateY(4px);
  }
  66% {
    opacity: 1;
    transform: translateY(1px);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}

.m-smooth .pop {
  animation: popSmooth 240ms cubic-bezier(0.2, 0.9, 0.3, 1.25);
}
@keyframes popSmooth {
  from {
    opacity: 0;
    transform: scale(0.85);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.m-stepped .pop {
  animation: popStep 333ms;
  animation-timing-function: step-end;
}
@keyframes popStep {
  0% {
    transform: scale(0.5);
  }
  25% {
    transform: scale(1.22);
  }
  50% {
    transform: scale(0.94);
  }
  75% {
    transform: scale(1);
  }
  100% {
    transform: none;
  }
}
.m-stepped .pop .burst {
  animation: burstStep 250ms;
  animation-timing-function: step-end;
}
@keyframes burstStep {
  0% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(0.85);
  }
  33% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1.08);
  }
  66%,
  100% {
    opacity: 0;
  }
}
.m-smooth .pop .burst {
  animation: burstSmooth 320ms ease-out;
}
@keyframes burstSmooth {
  from {
    opacity: 0.9;
    transform: translate(-50%, -50%) scale(0.85);
  }
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.15);
  }
}

@media (prefers-reduced-motion: reduce) {
  .dash *,
  .dash *::before,
  .dash *::after,
  .sheet *,
  .sheet *::before,
  .sheet *::after {
    animation: none !important;
    transition: none !important;
  }
}

